  "We email each friend once with a link to this task, and don't keep their address.": "我们会给每位朋友发一封带此任务链接的邮件，且不保存他们的地址。",
  "Calendar feed": "日历订阅",
  "Subscribe once and the tasks you signed up for or posted show up in your phone or computer calendar, and stay up to date.": "订阅一次，你报名或发布的任务就会显示在手机或电脑日历中，并保持更新。",
  "Get my calendar link": "获取我的日历链接",
