  "Description": "描述",
  "Copy link": "复制链接",
  "Subscribe in Apple Calendar": "在 Apple 日历中订阅",
  "Subscribe in Google Calendar": "在 Google 日历中订阅",
  "Anyone with this link can see your task list. If you shared it by mistake, reset it.": "任何拿到此链接的人都能看到你的任务列表。如果误分享了，请重置。",
  "Reset the link? The old one stops working, so calendars subscribed to it stop updating.": "重置链接？旧链接将失效，已订阅的日历会停止更新。",
