  "Nobody is on the leaderboard yet. Join and be the first!": "排行榜上还没有人。加入成为第一个吧！",
  "You're #{rank} with {hours} approved hours.": "你排名第 {rank}，已批准 {hours} 小时。",
  "You're on the leaderboard. Classmates see your first name, last initial and approved hours.": "你已上榜。同学能看到你的名字、姓氏首字母和已批准时长。",
  "Join to appear here. Only students at your school see it: your first name, last initial and approved hours.": "加入后会显示在这里。只有本校学生能看到：你的名字、姓氏首字母和已批准时长。",
  "Join the leaderboard": "加入排行榜",
  "Monthly progress email": "每月进度邮件",
  "On. After a month you logged hours, we'll email you on the 1st with what you logged and how close you are to your goal.": "已开启。在你记录过时长的月份之后，我们会在每月 1 日发邮件告诉你记录了什么、离目标还有多远。",
  "Off. We won't email you a monthly summary of your hours.": "已关闭。我们不会发送每月时长摘要邮件。",
