  "{school} has been asked to accept your transfer.": "已请 {school} 接受你的转校。",
  "You are already linked to another school. Joining asks {school} to accept your transfer, and your hours move with you.": "你已关联其他学校。加入会请 {school} 接受你的转校，你的时长也会一起转过去。",
  "Your hours will go to {school} for approval.": "你的时长会提交给 {school} 审批。",
  "Join {school}": "加入 {school}",
  "{name} invited you to VolunTrack": "{name} 邀请你使用 VolunTrack",
  "You're invited to VolunTrack": "你被邀请使用 VolunTrack",
  "Track your volunteer hours free: log hours in a minute, see your goal, and download a report when it is due.": "免费记录志愿时长：一分钟记录时长，查看目标，到期时下载报告。",
  "Log hours in under a minute, from your phone.": "用手机不到一分钟就能记录时长。",
