  "You already have an account.": "你已有账户。",
  "I track my volunteer hours on VolunTrack. It is free. Join me:": "我用 VolunTrack 记录志愿时长，免费的。一起来吧：",
  "Earn the Bring a Friend badge when a friend joins with your link.": "朋友通过你的链接加入，即可获得“带朋友”徽章。",
  "{n} of 5 friends joined. Reach 5 for the Team Builder badge.": "已有 {n}/5 位朋友加入。满 5 位可获得“团队建设者”徽章。",
  "{n} friends joined. Thank you for spreading the word!": "已有 {n} 位朋友加入。谢谢你帮忙宣传！",
  "Volunteering is better together. Send friends your link so they can track their hours too.": "一起做志愿更有意思。把链接发给朋友，让他们也记录自己的时长。",
