  "Places your school works with. Hours you serve at them count toward your goals.": "你学校合作的地方。在那里服务的时长计入你的目标。",
  "Website": "网站",
  "Your children's volunteer hours": "孩子的志愿时长",
  "Could not load your children's hours": "无法加载孩子的时长",
  "The server did not answer. Your child's hours are safe — this page just could not fetch them.": "服务器没有响应。孩子的时长是安全的，只是此页面暂时无法获取。",
  "Ask your child for their link code — they'll find it in Settings → Family — then enter it to follow their hours.": "向孩子要关联码（在“设置 → 家庭”中），输入后即可查看他们的时长。",
  "The organizer's waiver: approving also agrees to it for your child": "组织者的免责声明：批准即代表替孩子同意",
  "Set a target and we'll track your progress toward it. The primary goal powers your dashboard ring.": "设定目标，我们会跟踪进度。主要目标会显示在主页的进度环上。",
  "Your logged hours are stored on this device. If you've created an account, some features above (Family sharing, school linking, cross-device sync, two-factor authentication) also store data on our server. Sign out below to clear your session.": "你记录的时长保存在本设备上。如果你创建了账户，上面的部分功能（家庭分享、关联学校、多设备同步、双重验证）也会在我们的服务器上保存数据。在下方退出登录可清除会话。",
  "Passkey added. You can use it the next time you sign in.": "通行密钥已添加，下次登录即可使用。",
  "Passkey removed.": "通行密钥已删除。",
  "Passkeys": "通行密钥",
  "After your password, confirm it’s you with Face ID, Touch ID, your fingerprint or your device PIN instead of typing a code. Keep your authenticator app too — its backup codes are how you get back in if you lose every device with a passkey.": "输入密码后，用面容 ID、触控 ID、指纹或设备 PIN 确认身份，无需输入代码。请保留身份验证器应用：如果所有带通行密钥的设备都丢失，备用码是重新登录的方式。",
  "Added {date}": "添加于 {date}",
  "last used {date}": "上次使用 {date}",
  "This device can’t create passkeys.": "此设备无法创建通行密钥。",
  "Add a passkey": "添加通行密钥",
  "If you lose this device, sign in with one of these instead of your passkey. Each works once, and this is the only time they're shown.": "如果丢失此设备，请用其中一个代码代替通行密钥登录。每个代码只能用一次，而且只会显示这一次。",
  "I've saved them": "我已保存",
