  "Requirements saved.": "要求已保存。",
  "Loading requirements…": "正在加载要求…",
  "Schools you assign to this template follow these sections instead of your defaults. A section left unset here uses your defaults, and a school can still set its own.": "分配到此模板的学校会采用这些部分，而不是你的默认设置。这里未设置的部分沿用你的默认设置，学校仍可自行设置。",
  "Every rule here applies to the students linked to your school. Anything you leave inherited follows your organization, or VolunTrack’s defaults if you have none.": "这里的每条规定都适用于关联到你学校的学生。保持继承的部分会沿用你的机构设置，没有的话则使用 VolunTrack 的默认设置。",
  "These are the defaults for every school you own. A school that sets its own version of a section keeps it — your changes reach the rest.": "这些是你名下所有学校的默认设置。自行设置了某部分的学校会保留自己的版本，你的更改会应用到其余学校。",
  "Inherit": "继承",
  "Set our own": "自行设置",
  "Set in this template": "在此模板中设置",
  "Set a default": "设置默认值",
  "Save requirements": "保存要求",
  "Require a proof file": "要求上传证明文件",
  "Require a supervisor name and email": "要求填写负责人姓名和邮箱",
  "Require a location": "要求填写地点",
  "Require the organization name": "要求填写机构名称",
  "Allow future-dated entries": "允许记录未来日期",
  "Minimum hours per entry": "每条记录最少时长",
  "No minimum": "无最低要求",
  "Maximum hours per entry": "每条记录最多时长",
  "Maximum hours on one day": "每天最多时长",
  "Log within N days of the activity": "活动后 N 天内记录",
  "Any time after": "之后任何时间",
  "Minimum description length": "描述最少字数",
  "Students can’t add, edit or delete entries dated before this, e.g. once a semester’s report is done. You can still add hours for them.": "学生不能添加、编辑或删除此日期之前的记录，例如学期报告完成后。你仍可为他们添加时长。",
  "Allowed categories": "允许的类别",
  "Leave all unchecked to accept every category.": "全部不勾选即接受所有类别。",
  "One per line. Hours from anywhere else still go in, but they're flagged in Students → Hours to check so you can look at them first. Leave empty to accept every place.": "每行一个。其他地方的时长仍会记入，但会在“学生 → 待核查时长”中标记，方便你先查看。留空即接受所有地方。",
  "Total hours required": "要求总时长",
  "None": "无",
  "Grades at your school": "你学校的年级",
  "Tick the grades you have, e.g. only 9th, or 10th–12th. Students then pick from these, must pick one to join, and “New school year” moves your top grade on. Leave all unticked to allow any grade.": "勾选你学校有的年级，例如只有 9 年级，或 10–12 年级。学生会从中选择，加入时必须选一个，“新学年”会让最高年级升级。全部不勾选即允许任何年级。",
  "Note to students": "给学生的说明",
  "Due before senior year begins.": "须在高四开学前完成。",
  "Per-grade overrides": "按年级设定",
  "A student in one of these grades is held to its number instead of the total above.": "这些年级的学生按各自年级的数字要求，而不是上面的总数。",
  "Minimum hours by type": "按类型的最低时长",
  "At least this many of a student’s hours must be of one type. They count toward the total, not on top of it.": "学生的时长中至少要有这么多属于某一类型。计入总数，不额外增加。",
  "Add a type": "添加类型",
  "+ Add a type…": "+ 添加类型…",
  "Grade (e.g. 11, Junior, Year 12)": "年级（例如：11、Junior、Year 12）",
  "Students must sign in with our school account (SSO)": "学生必须使用学校账户登录（SSO）",
  "Allowed email domains": "允许的邮箱域名",
  "No levels yet.": "还没有等级。",
  "Use Bronze, Silver, Gold": "使用铜、银、金",
  "Level name": "等级名称",
  "Add a level": "添加等级",
  "Hours count the same way as your requirement: everything logged except rejected entries.": "时长的计算方式与要求相同：除被拒绝的记录外全部计入。",
  "New signer: the old signature was removed. Draw theirs below, or use the phone QR code.": "签名人已更换，旧签名已删除。请在下方画出新签名，或使用手机二维码。",
  "What each entry needs": "每条记录需要什么",
  "Who signs": "谁签名",
  "Students sign on the Log Hours form before they can save.": "学生在“记录时长”表单上签名后才能保存。",
  "Students must name a supervisor, who gets an emailed link and signs there to approve.": "学生必须填写负责人，负责人会收到邮件链接并在其中签名批准。",
  "Students sign on the form, and their supervisor signs on the emailed link to approve.": "学生在表单上签名，负责人在邮件链接中签名批准。",
  "Link to your form": "你的表格链接",
  "Google Form — students fill it in right on the Log Hours page, then tick a box to say they sent it.": "Google 表单：学生直接在“记录时长”页面填写，然后勾选已提交。",
  "A Google Form opens right on the Log Hours page. Any other link (a PDF, a doc) is something students download, get signed, and upload. Leave blank if they get the form in class.": "Google 表单会直接在“记录时长”页面打开。其他链接（PDF、文档）则由学生下载、签字后再上传。如果在课堂上发表格，请留空。",
  "This looks like the link for editing the form. Use Send → link in Google Forms instead, so students can fill it in.": "这看起来是编辑表单的链接。请在 Google 表单中使用“发送 → 链接”，学生才能填写。",
  "Short forms.gle links can’t open inside VolunTrack. Paste the full docs.google.com link to keep students on the page.": "forms.gle 短链接无法在 VolunTrack 内打开。请粘贴完整的 docs.google.com 链接，让学生留在页面上。",
  "Note to students (optional)": "给学生的说明（可选）",
  "Your supervisor must sign in blue or black ink.": "负责人必须用蓝色或黑色墨水签名。",
  "Advisor name": "指导老师姓名",
  "Answer type": "回答类型",
  "Choices": "选项",
  "First period, Second period, Third period": "第一节、第二节、第三节",
