  "Loading branding…": "正在加载品牌设置…",
  "Accent colour": "强调色",
  "A hex value. Used for accents on your sign-in page — not for text or button backgrounds, so any colour stays readable. Leave blank for the VolunTrack green.": "十六进制值。用于登录页的强调元素，不用于文字或按钮背景，所以任何颜色都清晰易读。留空则使用 VolunTrack 绿色。",
  "Enter a hex value like #2f855a.": "请输入十六进制值，例如 #2f855a。",
  "Preview": "预览",
  "Save branding": "保存品牌设置",
  "This branding applies to your organization’s own hostnames. Each school brands its own separately.": "此品牌设置适用于你机构自有的主机名。每所学校单独设置自己的品牌。",
  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "只有你学校的登录页会改变。主站仍保留 VolunTrack 的名称和标志。",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "品牌只显示在你自己的主机名上。你还没有可用的域名，请先在“自定义域名”中设置，之后这里保存的内容会显示在它的登录页上。",
  "Shown at sign-in on": "显示于以下登录页",
