  "When I'm free": "我有空时",
  "Edit when you are free": "编辑你的空闲时间",
  "When are you usually free?": "你通常什么时候有空？",
  "Tick the times that work for you. \"When I'm free\" then shows only events that start then. Only you see this.": "勾选适合你的时间。\"我有空时\"只会显示在这些时间开始的活动。只有你能看到。",
  "Morning is before noon, afternoon noon to 5 PM, evening after 5 PM.": "上午指中午之前，下午指中午至下午 5 点，晚上指下午 5 点以后。",
  "Could not save when you are free.": "无法保存你的空闲时间。",
